auto folderSddl = get_auto_start_folder_sddl();
if (folderSddl.empty())
{
    Logger::error(L"Unable to resolve the current user SID for task folder ACL");
    return false;
}

winrt::check_hresult(pRootFolder->CreateFolder(
    _bstr_t(L"\\PowerToys"),
    _variant_t(folderSddl.c_str()),
    &pTaskFolder));

std::vector<std::wstring> taskNames = SnapshotTaskNames(pTaskFolder);
pTaskCollection.Reset();
HRESULT firstFailure = S_OK;
for (const auto& taskName : taskNames)
{
    const HRESULT deleteHr = pTaskFolder->DeleteTask(_bstr_t(taskName.c_str()), 0);
    if (FAILED(deleteHr) && !IsNotFound(deleteHr) && SUCCEEDED(firstFailure))
    {
        firstFailure = deleteHr;
    }
}

// Re-enumerate for observability, release the folder, then delete it.

if (IsAccessDenied(cleanupHr))
{
    const auto repairSddl = BuildCleanupFolderSddl();
    const HRESULT aclHr = pTaskFolder->SetSecurityDescriptor(
        _bstr_t(repairSddl.c_str()), 0);
    LogCleanupRetry(cleanupHr, aclHr);
    if (SUCCEEDED(aclHr))
    {
        cleanupHr = DeleteTasksAndFolderOnce(...);
    }
}

// Preserve Return="ignore".
// In the custom action:
if (FAILED(finalHr) && IsInteractiveMsiSession(hInstall))
{
    MsiProcessMessage(hInstall, INSTALLMESSAGE_WARNING, &record);
}

